package glitch

import data.glitch_lib

credential_keywords := {
    "password", "passwd", "pwd", "secret", "credentials", "auth_token",
    "api_key", "apikey", "access_key", "secret_key", "private_key",
    "account_key", "username", "user_name", "login", "admin_user",
    "root_user", "service_account", "default_user", "connection_string",
    "conn_string", "dsn", "certificate", "cert", "pem", "rsa_key",
    "dsa_key", "ecdsa_key", "ed25519_key", "tls_key", "ssl_key",
    "ssh_key", "recovery_password", "maintenance_password",
    "diagnostic_password", "initial_password", "first_boot_password",
    "setup_password", "admin_password_enabled", "disable_password_authentication"
}

default_credentials := {
    "admin", "password", "root", "default", "123456", "changeme",
    "password123", "admin123", "root123", "guest", "user", "test"
}

is_credential_key(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

is_string_literal(node) {
    node.ir_type == "String"
    count(node.value) > 0
    not regex.match("^\\$\\{.*\\}$", node.value)
    not regex.match("^(vault|data|var|module|secret|keyvault|azuread)\\.\\.", node.value)
}

is_base64_like(value) {
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", value)
}

is_hex_like(value) {
    regex.match("^[0-9a-fA-F]{8,}$", value)
}

is_private_key_material(value) {
    regex.match("(?i)-----BEGIN (RSA |DSA |EC |OPENSSH |PGP )?(PRIVATE KEY|CERTIFICATE)-----", value)
}

is_connection_string_with_auth(value) {
    regex.match("(?i)[a-z]+://[^/]+:[^@]+@", value)
}

contains_default_credential(value) {
    default := default_credentials[_]
    contains(lower(value), default)
}

is_suspicious_value(node) {
    is_string_literal(node)
    val := node.value
    count(val) > 3
    not regex.match("^[A-Z][a-z]+_[A-Z_]+$", val)
}

check_attribute_for_hardcoded_credential(attr) {
    is_credential_key(attr.name)
    is_suspicious_value(attr.value)
    val := attr.value.value
    not regex.match("^(\\$[A-Z_]+|\\{[A-Z_]+\\})$", val)
}

check_attribute_for_hardcoded_credential(attr) {
    is_credential_key(attr.name)
    attr.value.ir_type == "String"
    val := attr.value.value
    is_private_key_material(val)
}

check_attribute_for_hardcoded_credential(attr) {
    is_credential_key(attr.name)
    attr.value.ir_type == "String"
    is_connection_string_with_auth(attr.value.value)
}

check_nested_credential(parent_name, value_node) {
    is_credential_key(parent_name)
    is_suspicious_value(value_node)
}

check_nested_credential(parent_name, value_node) {
    is_credential_key(parent_name)
    value_node.ir_type == "String"
    is_private_key_material(value_node.value)
}

check_nested_value(parent_name, node) {
    node.ir_type == "Hash"
    [k, v] := node.value[_]
    k.ir_type == "String"
    check_nested_credential(parent_name, v)
}

check_nested_value(parent_name, node) {
    node.ir_type == "Hash"
    [k, v] := node.value[_]
    k.ir_type == "String"
    inner_name := sprintf("%s_%s", [parent_name, k.value])
    is_credential_key(inner_name)
    check_nested_value(inner_name, v)
}

check_array_for_credentials(parent_name, node) {
    node.ir_type == "Array"
    item := node.value[_]
    is_suspicious_value(item)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    check_attribute_for_hardcoded_credential(attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Credentials should not be hard-coded in configuration files. (CWE-798)"
    }
}

